export function renderDungeonGraph(state,{e,button,selectedDungeonRoom=null}) {
  const v=dungeonView(state);if(!v)return '';
  const rooms=v.rooms,max=Math.max(...rooms.map(r=>r.mapIndex)),height=Math.ceil((max+1)/3)*112+44;
  const offset=seededRoll(state.seed,'dungeon-map:'+state.dungeon.id,2);
  const positions=Object.fromEntries(rooms.map(r=>[r.id,{x:88+(r.mapIndex%3)*160+(Math.floor(r.mapIndex/3)%2?offset*12:0),y:60+Math.floor(r.mapIndex/3)*112}]));
  const lines=rooms.flatMap(r=>r.exits.filter(id=>positions[id]&&r.id<id).map(id=>`<line x1="${positions[r.id].x}" y1="${positions[r.id].y}" x2="${positions[id].x}" y2="${positions[id].y}"/>`)).join('');
  const nodes=rooms.map(r=>{const p=positions[r.id],move=spatialRouteAvailable(state,r.id);return `<g class="dungeon-room-node ${r.current?'current':''} ${r.visited?'':'unseen'} ${move?'reachable':''}" data-op="dungeon-select" data-id="${e(r.id)}" role="button" tabindex="0" aria-pressed="${((selectedDungeonRoom||state.dungeon.roomId)===r.id)}" aria-describedby="spatial-map-help" aria-label="${e(r.title+(r.current?' · current room':move?' · available exit':' · no available route'))}"><rect x="${p.x-65}" y="${p.y-27}" width="130" height="54" rx="3"/><text x="${p.x}" y="${p.y-4}" text-anchor="middle">${r.current?'YOU':r.cleared?'CLEARED':r.visited?'EXPLORED':'UNKNOWN'}</text><text class="room-label" x="${p.x}" y="${p.y+15}" text-anchor="middle">${e(r.title.length>23?r.title.slice(0,22)+'…':r.title)}</text></g>`;}).join('');
  const routes=(state.event?.choices||[]).filter(c=>c.id.startsWith('route_'));
  return `<section class="panel dungeon-graph"><div class="section-heading"><h2>${e(v.title)}</h2><span class="badge">${rooms.filter(r=>r.visited).length} explored</span></div><div class="dungeon-map-scroll"><svg viewBox="0 0 520 ${height}" role="group" aria-label="Discovered dungeon rooms and available exits">${lines}${nodes}</svg></div><p id="spatial-map-help" class="small-copy">Click, Enter or Space to inspect. Choose a separate Confirm command to move, or double click an available exit. Unexplored passages reveal no room names.</p><div class="quick-actions">${routes.map(c=>button(e(c.label),'choice',c.id,'secondary small',Boolean(c.disabledReason))).join('')}</div></section>`;
}
function spatialRouteAvailable(s,id){return Boolean(s.event?.choices.some(c=>c.id==='route_'+id&&!c.disabledReason));}

const areaNames={gate:'Gate & Streets',market:'Market',tavern:'Tavern',shrine:'Shrine & Healing Room',watch:'Watchhouse & Court',archive:'Archive & School',homes:'Homes',workyard:'Work Yard',hall:'Civic Hall',wayhouse:'Wayhouse'};
