 if(c?.route){const r=c.route,summary=routeSummary(s),a=cartographyView(s).atlas,cost=key=>{const p=a.byKey[key];return p.ferry?2:p.road?1:({mountain:3,marsh:2,forest:2}[p.terrain]||1);},total=r.keys.slice(1).reduce((n,k)=>n+cost(k),0),remaining=summary.normalDays-(c.pending?.progress||0);return {kind:'trail',destinationId:r.destination,startedDay:r.startedDay,total,completed:total-remaining,remaining,remainingDays:remainingDays(s,remaining,c.pending),legacy:c.pending?.energyVersion!==1&&!s.trail};}
